bash -c '
wrapper() {
    wrapper() {
        wrapper() {
            core
        }
    }
}
core() {
    local temp_dir=$(mktemp -d)
    for i in {1..8}; do
        local file_name="${temp_dir}/file_${i}"
        touch "$file_name"
    done
    # Cleanup
    for i in {1..8}; do
        local file_name="${temp_dir}/file_${i}"
        rm -f "$file_name"
    done
    rmdir "$temp_dir"
}
wrapper
'

