import os

fd_list = []

try:
    while True:
        fd = os.open("/dev/null", os.O_RDONLY)
        fd_list.append(fd)
        print(f"Opened FD: {fd}")
except KeyboardInterrupt:
    print("Interrupted")
finally:
    for fd in fd_list:
        os.close(fd)
        print(f"Closed FD: {fd}")

