import os
fd_count = 0
try:
    while True:
        fd = os.open("/dev/null", os.O_RDONLY)
        fd_count += 1
        if fd_count > 2:
            os.close(fd - 1)
            fd_count -= 1
        print(f"Открыт FD: {fd}")
except KeyboardInterrupt:
    print("Цикл прерван")

