import os
import sys

def open_files(limit):
    fds = []
    try:
        while True:
            fd = os.open("/dev/null", os.O_RDONLY)
            fds.append(fd)
            if len(fds) > limit:
                os.close(fds.pop(0))
    except KeyboardInterrupt:
        pass
    finally:
        for fd in fds:
            os.close(fd)

if __name__ == "__main__":
    open_files(2)
'

